          {!!item.files.length && <div className="flex flex-wrap gap-2" aria-label="Article and download actions">{item.files.filter((f: any) => f.name === "article.html").map((f: any) => <span key={f.id} className="contents"><button className={primary} onClick={() => setPreview(f)}>Preview article</button>{!snapshot.wordpress?.connections?.length && <button className={button} disabled={busy} onClick={() => void act(() => copyForWordPress(f, item.files))}>Copy for WordPress</button>}<a className={button} href={`/api/recipe-intelligence/artifacts/${f.id}`}>Download article</a></span>)}<a className={button} href={`/api/recipe-intelligence/items/${item.id}/zip`}>Download all (ZIP)</a></div>}
