          <details className={disclosure}><summary className="cursor-pointer text-sm text-gray-600">Processing details and repair</summary><p className="mt-3 text-sm text-gray-600">{item.selection_reason} Repairs reuse saved responses. Replacements make a new paid request within your approved budget.</p>{item.article && <button className={`${button} mt-3`} disabled={busy} onClick={() => void act(() => request(`items/${item.id}/retry`, "POST", { kind: "save_article" }))}>Repair saved article files (no charge)</button>}<div className="mt-3 grid gap-2 sm:grid-cols-2 lg:grid-cols-3">{item.stages.filter((s: any) => s.state !== "waiting").map((s: any) => <div key={s.id} className="space-y-2 rounded-xl border border-gray-200 p-3 text-xs"><p>{stageLabel(s.kind, item)} · {label(s.state)}</p>{s.error && <p className="text-red-700">{s.error}</p>}{(["featured", "alternate", "pinterest"].includes(s.kind) || s.kind.startsWith("photo:")) && s.state === "done" && <button className={button} disabled={busy} onClick={() => void act(() => request(`items/${item.id}/retry`, "POST", { kind: s.kind }))}>Repair saved image (no charge)</button>}{(["article", "featured", "alternate", "pinterest"].includes(s.kind) || s.kind.startsWith("photo:")) && ["done", "failed"].includes(s.state) && <button className={button} disabled={busy} onClick={() => void act(() => request(`items/${item.id}/retry`, "POST", { kind: s.kind, regenerate: true }))}>Generate replacement within approved budget</button>}</div>)}</div></details>
          {!!item.files.length && <details className={disclosure}><summary className="cursor-pointer text-sm text-gray-600">Other formats, prompts and recipe data</summary><div className="mt-3 flex flex-wrap gap-2">{item.files.filter((f: any) => f.name !== "article.html" && (!f.media_type.startsWith("image/") || !!item.photos?.length && !/\.(jpg|jpeg|png|webp)$/i.test(f.name))).map((f: any) => <a key={f.id} className={`${button} break-all`} href={`/api/recipe-intelligence/artifacts/${f.id}`}>Download {f.name}</a>)}</div></details>}
